import { BrowserRouter, Routes, Route, NavLink } from "react-router-dom";

function Home() { return <h1>Home</h1>; }
function About() { return <h1>About</h1>; }
function NotFound() { return <h1>404 - Not found</h1>; }

export default function App() {
  return (
    <BrowserRouter>
      <nav>
        <NavLink to="/" end>Home</NavLink>{" | "}
        <NavLink to="/about" className={({ isActive }) => (isActive ? "active" : "")}>About</NavLink>
      </nav>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </BrowserRouter>
  );
}

const routes = {
  "/": () => <h2>Home page</h2>,
  "/about": () => <h2>About page</h2>,
  "/contact": () => <h2>Contact page</h2>,
};

function App() {
  const [path, setPath] = useState("/");
  const Page = routes[path] || (() => <h2>404 Not Found</h2>);
  const link = (to, label) => (
    <a
      href={to}
      onClick={(e) => { e.preventDefault(); setPath(to); }}
      style={{ marginRight: 10, fontWeight: path === to ? "bold" : "normal" }}
    >
      {label}
    </a>
  );
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <nav>{link("/", "Home")}{link("/about", "About")}{link("/contact", "Contact")}{link("/nope", "Broken")}</nav>
      <Page />
      <small>Current path (state): {path}</small>
    </div>
  );
}

import { Outlet, NavLink, Routes, Route } from "react-router-dom";

function DashboardLayout() {
  return (
    <div style={{ display: "flex" }}>
      <aside>
        <NavLink to="/dashboard" end>Overview</NavLink><br />
        <NavLink to="/dashboard/settings">Settings</NavLink>
