function ProductList() {
  const [params, setParams] = useSearchParams();
  const sort = params.get("sort") ?? "asc";
  return (
    <>
      <button onClick={() => setParams({ sort: sort === "asc" ? "desc" : "asc" })}>
        Sort: {sort}
      </button>
      <Link to="/products/7">Product 7</Link>
    </>
  );
}

function ProductDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  return (
    <>
      <h2>Product #{Number(id)}</h2>
      <button onClick={() => navigate(-1)}>Back</button>
      <button onClick={() => navigate("/cart", { state: { added: id } })}>Add to cart</button>
    </>
  );
}

import { createBrowserRouter, RouterProvider, useLoaderData, Form, redirect, useRouteError } from "react-router-dom";

async function postsLoader() {
  const res = await fetch("/api/posts");
  if (!res.ok) throw new Response("Failed", { status: res.status });
  return res.json();
}

async function createPostAction({ request }) {
  const form = await request.formData();
  await fetch("/api/posts", { method: "POST", body: JSON.stringify({ title: form.get("title") }) });
  return redirect("/posts");
}

function Posts() {
  const posts = useLoaderData();
  return (
    <>
      <ul>{posts.map((p) => <li key={p.id}>{p.title}</li>)}</ul>
      <Form method="post">
        <input name="title" required />
        <button>Add post</button>
      </Form>
    </>
  );
}

function ErrorPage() {
  const err = useRouteError();
  return <p>Oops: {err.status ?? err.message}</p>;
}

const router = createBrowserRouter([
  { path: "/posts", element: <Posts />, loader: postsLoader, action: createPostAction, errorElement: <ErrorPage /> },
]);

export default function App() {
  return <RouterProvider router={router} />;
}

import { Navigate, Outlet, useLocation, useNavigate, Routes, Route } from "react-router-dom";
import { useAuth } from "./AuthContext";

function RequireAuth({ role }) {
  const { user, loading } = useAuth();
  const location = useLocation();
  if (loading) return <p>Checking session...</p>;
  if (!user) return <Navigate to="/login" replace state={{ from: location }} />;
  if (role && user.role !== role) return <p>403 - Forbidden</p>;
  return <Outlet />;
}

function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname ?? "/dashboard";

  async function handleSubmit(e) {
    e.preventDefault();
    await login(new FormData(e.currentTarget));
    navigate(from, { replace: true });
  }
  return <form onSubmit={handleSubmit}><input name="email" /><button>Log in</button></form>;
}

export default function AppRoutes() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route element={<RequireAuth />}>
        <Route path="/dashboard" element={<h1>Dashboard</h1>} />
      </Route>
      <Route element={<RequireAuth role="admin" />}>
        <Route path="/admin" element={<h1>Admin</h1>} />
      </Route>
    </Routes>
  );
}

import { lazy, Suspense, useEffect } from "react";
import { Routes, Route, useLocation } from "react-router-dom";

const Home = lazy(() => import("./pages/Home"));
const Reports = lazy(() => import("./pages/Reports"));

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => { window.scrollTo(0, 0); }, [pathname]);
  return null;
}

export default function App() {
  return (
    <>
      <ScrollToTop />
      <Suspense fallback={<p>Loading page...</p>}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/reports" element={<Reports />} />
          <Route path="*" element={<h1>404</h1>} />
        </Routes>
      </Suspense>
    </>
  );
}
